Future<void> openGuidedInspection(BuildContext context) => Navigator.of(context).push(MaterialPageRoute(builder: (_) => const GuidedInspectionScreen()));

enum InspectionZone { engine, wheel, dashboard }

class GuidedInspectionScreen extends StatefulWidget { const GuidedInspectionScreen({super.key}); @override State<GuidedInspectionScreen> createState() => _GuidedInspectionScreenState(); }
class _GuidedInspectionScreenState extends State<GuidedInspectionScreen> {
  CameraController? controller; InspectionZone zone = InspectionZone.engine; String? error; bool analyzing = false; VehicleVisionResult? vision;
  @override void initState() { super.initState(); _openCamera(); }
  Future<void> _openCamera() async { try { final cameras = await availableCameras(); if (cameras.isEmpty) throw Exception('No camera'); controller = CameraController(cameras.first, ResolutionPreset.high, enableAudio: false); await controller!.initialize(); if(mounted)setState(() {}); await Future<void>.delayed(const Duration(milliseconds:700)); await _analyzeFrame(); } catch (_) { if(mounted)setState(()=>error='No pudimos iniciar la cámara.'); } }
  Future<void> _analyzeFrame() async { if (controller == null || analyzing) return; setState(() => analyzing = true); try { final photo = await controller!.takePicture(); final result = await VehicleVisionService().analyze(photo.path); if (mounted) { setState(() => vision = result); final message = result.labels.isEmpty ? 'No identificamos una zona con suficiente detalle. Acércate y confirma visualmente.' : 'Análisis visual: ${result.labels.join(', ')}'; ScaffoldMessenger.of(context).showSnackBar(SnackBar(content: Text(message))); } } catch (_) { if (mounted) setState(() => vision = const VehicleVisionResult(labels: [])); } finally { if (mounted) setState(() => analyzing = false); } }
  @override void dispose(){controller?.dispose();super.dispose();}
  @override Widget build(BuildContext context) { final item=_item(); return Scaffold(backgroundColor:Colors.black,body:Stack(fit:StackFit.expand,children:[if(controller?.value.isInitialized==true)CameraPreview(controller!) else Center(child:error==null?const CircularProgressIndicator(color:AppTheme.teal):Text(error!,style:const TextStyle(color:Colors.white))),const DecoratedBox(decoration:BoxDecoration(gradient:LinearGradient(begin:Alignment.topCenter,end:Alignment.bottomCenter,colors:[Color(0x99000000),Colors.transparent,Color(0xBB000000)]))),SafeArea(child:Padding(padding:const EdgeInsets.all(20),child:Column(children:[Row(children:[IconButton.filledTonal(onPressed:()=>Navigator.pop(context),icon:const Icon(CupertinoIcons.xmark),style:IconButton.styleFrom(backgroundColor:Colors.black45,foregroundColor:Colors.white)),const Spacer(),const Text('INSPECCIÓN GUIADA',style:TextStyle(color:Colors.white,fontWeight:FontWeight.w800,letterSpacing:1))]),const SizedBox(height:20),_ZonePicker(selected:zone,onChanged:(v)=>setState(()=>zone=v)),const Spacer(),_TargetFrame(icon:item.icon,color:item.color),const SizedBox(height:18),Text(item.instruction,textAlign:TextAlign.center,style:const TextStyle(color:Colors.white,fontSize:20,fontWeight:FontWeight.w700)),const SizedBox(height:8),const Text('Encuadra la zona y confirma tu revisión visual.',textAlign:TextAlign.center,style:TextStyle(color:Colors.white70)),const SizedBox(height:22),_InspectionResult(icon:item.icon,title:item.title,status:item.status,detail:item.detail,color:item.color),const SizedBox(height:16),FilledButton.icon(style:FilledButton.styleFrom(backgroundColor:AppTheme.teal,minimumSize:const Size.fromHeight(52)),onPressed:()=>_confirm(item),icon:const Icon(CupertinoIcons.checkmark_seal_fill),label:const Text('Confirmar revisión visual'))])))])); }
  Future<void> _confirm(_InspectionItem item) async { if (vision?.hasVehicleCue != true) { ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content: Text('Primero captura una imagen donde se identifique el vehículo o la zona.'))); return; } final app = ProviderScope.containerOf(context).read(appProvider); await app.addInspection(InspectionRecord(zone: item.title, date: DateTime.now(), notes: item.detail)); if (mounted) { ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content: Text('Revisión visual guardada'))); } }
  _InspectionItem _item() { final identified = vision?.hasVehicleCue == true; final uncertain = vision != null && !identified; final status = vision == null ? 'Pendiente de captura' : uncertain ? 'Revisión manual' : 'Zona identificada'; final color = uncertain ? Colors.orangeAccent : const Color(0xFF5BEBDD); switch(zone) { case InspectionZone.engine: return _InspectionItem(CupertinoIcons.car_detailed,'Compartimento del motor',status,uncertain ? 'La imagen no es concluyente. Confirma visualmente fugas o piezas sueltas.' : identified ? 'Zona compatible identificada. Confirma visualmente el estado.' : 'Observa fugas, piezas sueltas o señales visibles de desgaste.',color,'Apunta al compartimento del motor'); case InspectionZone.wheel:return _InspectionItem(CupertinoIcons.wrench,'Frenos y pastillas',status,uncertain ? 'La imagen no es concluyente. Confirma visualmente el desgaste.' : identified ? 'Zona compatible identificada. Confirma visualmente el estado.' : 'Observa el disco y la pastilla sin sustituir una revisión profesional.',color,'Apunta a una rueda del vehículo'); case InspectionZone.dashboard:return _InspectionItem(CupertinoIcons.speedometer,'Tablero y estado general',status,uncertain ? 'La imagen no es concluyente. Confirma visualmente los testigos.' : identified ? 'Zona compatible identificada. Confirma visualmente el estado.' : 'Comprueba testigos encendidos y daños visibles.',color,'Apunta al tablero o al vehículo completo'); } }
}
class _ZonePicker extends StatelessWidget { const _ZonePicker({required this.selected,required this.onChanged}); final InspectionZone selected; final ValueChanged<InspectionZone> onChanged; @override Widget build(BuildContext context)=>Container(padding:const EdgeInsets.all(5),decoration:BoxDecoration(color:const Color(0x99000000),borderRadius:BorderRadius.circular(28)),child:Row(children:[_button(InspectionZone.engine,CupertinoIcons.drop_fill,'Motor'),_button(InspectionZone.wheel,CupertinoIcons.wrench,'Frenos'),_button(InspectionZone.dashboard,CupertinoIcons.speedometer,'Estado')])); Widget _button(InspectionZone z,IconData i,String label){final active=z==selected;return Expanded(child:GestureDetector(onTap:()=>onChanged(z),child:AnimatedContainer(duration:const Duration(milliseconds:180),padding:const EdgeInsets.symmetric(vertical:10),decoration:BoxDecoration(color:active?const Color(0xFF00AFA5):Colors.transparent,borderRadius:BorderRadius.circular(23)),child:Column(mainAxisSize:MainAxisSize.min,children:[Icon(i,color:Colors.white,size:20),const SizedBox(height:3),Text(label,style:const TextStyle(color:Colors.white,fontSize:12,fontWeight:FontWeight.w700))]))));} }
class _TargetFrame extends StatelessWidget { const _TargetFrame({required this.icon,required this.color}); final IconData icon; final Color color; @override Widget build(BuildContext context){final width=MediaQuery.sizeOf(context).width<360?MediaQuery.sizeOf(context).width-72.0:240.0;return Container(width:width,height:170,decoration:BoxDecoration(border:Border.all(color:color,width:3),borderRadius:BorderRadius.circular(30),boxShadow:[BoxShadow(color:color.withValues(alpha:.45),blurRadius:18)]),child:Center(child:Icon(icon,size:56,color:color)));} }
class _InspectionResult extends StatelessWidget { const _InspectionResult({required this.icon,required this.title,required this.status,required this.detail,required this.color}); final IconData icon; final String title,status,detail; final Color color; @override Widget build(BuildContext context)=>Container(width:double.infinity,padding:const EdgeInsets.all(16),decoration:BoxDecoration(color:const Color(0xF2FFFFFF),borderRadius:BorderRadius.circular(22)),child:Row(crossAxisAlignment:CrossAxisAlignment.start,children:[CircleAvatar(radius:23,backgroundColor:color.withValues(alpha:.15),child:Icon(icon,color:color)),const SizedBox(width:12),Expanded(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(title,maxLines:2,overflow:TextOverflow.ellipsis,style:const TextStyle(color:Color(0xFF102B31),fontWeight:FontWeight.w800,fontSize:16)),const SizedBox(height:5),Text(detail,maxLines:4,overflow:TextOverflow.ellipsis,style:const TextStyle(color:Color(0xFF64727B),height:1.2)),const SizedBox(height:8),Container(padding:const EdgeInsets.symmetric(horizontal:9,vertical:5),decoration:BoxDecoration(color:color.withValues(alpha:.14),borderRadius:BorderRadius.circular(12)),child:Text(status,style:TextStyle(color:color,fontWeight:FontWeight.w800,fontSize:12))) ]))])); }
class _InspectionItem { const _InspectionItem(this.icon,this.title,this.status,this.detail,this.color,this.instruction); final IconData icon; final String title,status,detail,instruction; final Color color; }
